    def is_bipartite(graph, start, colors):
        stack = [(start, 0)]
        colors[start] = 0
        while stack:
            node, color = stack.pop()
            for neighbor in graph[node]:
                if colors[neighbor] == -1:
                    colors[neighbor] = 1 - color
                    stack.append((neighbor, 1 - color))
                elif colors[neighbor] == color:
                    return False
        return True

